create table if not exists public.sdr_agents (id uuid primary key default gen_random_uuid(), name text not null default 'SDR IA Club4', description text, status text not null default 'draft' check (status in ('draft','active','paused')), channel text not null default 'whatsapp' check (channel in ('whatsapp','other')), tone text default 'consultivo', language text default 'pt-BR', prompt text default '', fallback_enabled boolean not null default true, handoff_enabled boolean not null default true, timezone text not null default 'America/Sao_Paulo', created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sdr_integrations (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, provider text not null default 'whatsapp_cloud', status text not null default 'disconnected' check (status in ('disconnected','pending','connected','error')), phone_number text, display_name text, webhook_url text, last_sync_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sdr_knowledge (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, title text not null, category text not null default 'geral', content text not null default '', source_url text, priority integer not null default 50 check (priority between 0 and 100), enabled boolean not null default true, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sdr_blocks (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, name text not null, block_type text not null default 'response' check (block_type in ('greeting','qualification','objection','response','handoff','closing','follow_up','other')), trigger_text text, content text not null default '', variables jsonb not null default '[]'::jsonb, enabled boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sdr_prompt_versions (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, version integer not null, name text not null default 'Prompt principal', prompt text not null default '', is_active boolean not null default false, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), unique(agent_id, version));
create table if not exists public.sdr_business_hours (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, weekday integer not null check (weekday between 0 and 6), enabled boolean not null default true, start_time time not null default '08:00', end_time time not null default '18:00', unique(agent_id, weekday));
create table if not exists public.sdr_appointments (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, lead_id uuid references public.leads(id) on delete set null, customer_id uuid references public.customers(id) on delete set null, contact_name text not null, contact_phone text, title text not null default 'Reunião comercial', starts_at timestamptz not null, ends_at timestamptz, status text not null default 'scheduled' check (status in ('scheduled','confirmed','completed','cancelled','no_show')), notes text, external_id text, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_at is null or ends_at > starts_at));
create table if not exists public.sdr_conversations (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, lead_id uuid references public.leads(id) on delete set null, customer_id uuid references public.customers(id) on delete set null, phone text not null, contact_name text, status text not null default 'open' check (status in ('open','waiting','handoff','closed')), mode text not null default 'ai' check (mode in ('ai','human','paused')), unread_count integer not null default 0 check (unread_count >= 0), last_message_at timestamptz, summary text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.sdr_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.sdr_conversations(id) on delete cascade, direction text not null check (direction in ('inbound','outbound')), sender_type text not null check (sender_type in ('contact','ai','human','system')), message_type text not null default 'text', body text, external_id text, status text not null default 'sent' check (status in ('queued','sent','delivered','read','failed')), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.sdr_automation_rules (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.sdr_agents(id) on delete cascade, name text not null, event text not null, action text not null, delay_minutes integer not null default 0 check (delay_minutes >= 0), enabled boolean not null default true, config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_sdr_integrations_agent on public.sdr_integrations(agent_id);
create index if not exists idx_sdr_knowledge_agent_enabled on public.sdr_knowledge(agent_id, enabled, priority desc);
create index if not exists idx_sdr_blocks_agent_enabled_order on public.sdr_blocks(agent_id, enabled, sort_order);
create index if not exists idx_sdr_prompts_agent_active on public.sdr_prompt_versions(agent_id, is_active);
create index if not exists idx_sdr_appointments_agent_start on public.sdr_appointments(agent_id, starts_at);
create index if not exists idx_sdr_conversations_agent_last on public.sdr_conversations(agent_id, last_message_at desc);
create index if not exists idx_sdr_messages_conversation_created on public.sdr_messages(conversation_id, created_at);
create index if not exists idx_sdr_automation_agent_enabled on public.sdr_automation_rules(agent_id, enabled);

alter table public.sdr_agents enable row level security;
alter table public.sdr_integrations enable row level security;
alter table public.sdr_knowledge enable row level security;
alter table public.sdr_blocks enable row level security;
alter table public.sdr_prompt_versions enable row level security;
alter table public.sdr_business_hours enable row level security;
alter table public.sdr_appointments enable row level security;
alter table public.sdr_conversations enable row level security;
alter table public.sdr_messages enable row level security;
alter table public.sdr_automation_rules enable row level security;

create policy sdr_agents_manage on public.sdr_agents for all to authenticated using ((select public.current_user_role()) in ('admin','manager') or created_by=(select auth.uid())) with check ((select public.current_user_role()) in ('admin','manager') or created_by=(select auth.uid()));
create policy sdr_integrations_manage on public.sdr_integrations for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_knowledge_manage on public.sdr_knowledge for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_blocks_manage on public.sdr_blocks for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_prompts_manage on public.sdr_prompt_versions for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_hours_manage on public.sdr_business_hours for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_appointments_manage on public.sdr_appointments for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_conversations_manage on public.sdr_conversations for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_messages_manage on public.sdr_messages for all to authenticated using (exists (select 1 from public.sdr_conversations c join public.sdr_agents a on a.id=c.agent_id where c.id=conversation_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_conversations c join public.sdr_agents a on a.id=c.agent_id where c.id=conversation_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
create policy sdr_automation_manage on public.sdr_automation_rules for all to authenticated using (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid())))) with check (exists (select 1 from public.sdr_agents a where a.id=agent_id and ((select public.current_user_role()) in ('admin','manager') or a.created_by=(select auth.uid()))));
